css:
@import url('https://fonts.googleapis.com/css2?family=Bona+Nova+SC:ital,wght@0,400;0,700;1,400&family=Inter:ital,opsz,wght@0,14..32,100..900;1,14..32,100..900&family=Roboto+Slab:wght@100..900&family=Roboto:ital,wght@0,100;0,300;0,400;0,500;0,700;0,900;1,100;1,300;1,400;1,500;1,700;1,900&display=swap');


.print-format .table-bordered td, .print-format .table-bordered th, .table {
    border: 1px solid #000 !important;
}

.print-format td, .print-format th {
    padding: 5px 10px !important;
}

table {
    margin: 0px !important;
}

.department {
    position: relative;
    bottom: -5px;
}

.sec-table td,.sec-table  th {
    text-align: center;
}

td,th {
    font-weight: bold !important;
    color: #000 !important;
}

.third-table td{
    border-left: 1px solid #000 !important;
    /*border: 1px solid #000 !important;*/
}

.fourth-table td{
    border: none !important;
}

.border-none  {
    border-top: none !important;
    border-bottom: none !important;
}

input[type=checkbox] { 
    appearance: auto !important;
}

hr {
    position: relative;
    top: -7px;
    left: 84px;
    border-top: 1px dashed !important;
    margin: 0px !important;
    width: 282px;
}

.sign-table td, .sign-table th {
    text-align: center;
}

.sign-table .h-12 {
    height: 50px;
}

.last-table td, .last-table th{
    padding: 0px !important;
}

ul {
    margin: 0px !important;
    padding: 5px 2px;
    padding-left: 17px;
    font-size: 8px;
}

li{
    list-style: circle;
}
html{
    direction:ltr;
}

td#mbl {
    padding: 0px !important;
    text-align: center;
    width: 100px;
}

.mbl {
    font-size: 90px;
    text-align: center;
    color: silver !important;
    margin-top: -19px !important;
    font-weight: bold;
    font-family: math;
    height:70px;
    font-style: normal;
}

.pt-cash {
    text-align: center;
    font-weight: bold;
    margin:0 !important;
    padding:0 !important;
}

.talab {
    text-align: center;
    font-size: 34px;
    font-weight: bold;
    margin: 0px !important;
    padding:0 !important;
}

#last-head {
    font-size: 10px;
}
